import{_ as n,o as t,c as i,b6 as a}from"./chunks/framework.BUXTSoD9.js";const g=JSON.parse('{"title":"Seiten und Buttons nach UI-Designrichtlinien entwerfen","description":"","frontmatter":{},"headers":[],"relativePath":"de-de/stage-2/frontend/multi-product-ui/index.md","filePath":"de-de/stage-2/frontend/multi-product-ui/index.md"}'),s={name:"de-de/stage-2/frontend/multi-product-ui/index.md"};function r(l,e,u,o,d,h){return t(),i("div",null,[...e[0]||(e[0]=[a(`<h1 id="seiten-und-buttons-nach-ui-designrichtlinien-entwerfen" tabindex="-1">Seiten und Buttons nach UI-Designrichtlinien entwerfen <a class="header-anchor" href="#seiten-und-buttons-nach-ui-designrichtlinien-entwerfen" aria-label="Permalink to “Seiten und Buttons nach UI-Designrichtlinien entwerfen”">​</a></h1><p>Viele Menschen sagen: &quot;Ich moechte, dass die Seite ein bisschen mehr wie Apple aussieht&quot; oder &quot;Die Buttons sollten etwas hochwertiger wirken&quot;. Aber wenn es dann an die Umsetzung geht, haengt man oft an einer Frage fest:</p><p><strong>Woran sollte man sich eigentlich orientieren?</strong></p><p>Einen Screenshot abzubilden, bringt nur die Erkenntnis &quot;Aehnlichkeit&quot;. Wenn man jedoch die Designrichtlinien von Apple, Google, Microsoft und Atlassian oeffnet, stellt man fest, dass deren wahre Staerke nicht im visuellen Stil liegt, sondern darin, <strong>Designprobleme klar zu benennen</strong>: Was auf einer Seite zuerst hervorgehoben wird, wie Buttons gestuft werden, welche Operationen betont werden -- diese Beurteilungskriterien sind der Kern.</p><blockquote><p>Sich an Designrichtlinien zu orientieren, heisst nicht, &quot;wie jemand anderes auszusehen&quot;, sondern zu lernen, wie andere Urteile faellen.</p></blockquote><div class="info custom-block"><p class="custom-block-title">Warum man diese heute noch lernen sollte</p><p>Designregeln sind bereits in Modelle trainiert und werden von Designtools standardmaessig absorbiert. Selbst wenn man AI ein paar Screenshots gibt, kann sie diese erlernen. Dennoch ist es wichtig zu wissen, woher diese Regeln kommen und warum sie so definiert sind.</p></div><h2 id="zunaechst-einige-originalzitate-um-den-unterschied-zu-spueren" tabindex="-1">Zunaechst einige Originalzitate, um den Unterschied zu spueren <a class="header-anchor" href="#zunaechst-einige-originalzitate-um-den-unterschied-zu-spueren" aria-label="Permalink to “Zunaechst einige Originalzitate, um den Unterschied zu spueren”">​</a></h2><p>Wenn du bisher dachtest, &quot;Designrichtlinien handeln doch nur von Stil&quot;, dann lies zuerst einige offizielle Originaltexte.</p><p>Im Team sagt man oft Dinge wie:</p><ul><li>Mach mal ein Dropdown</li><li>Hier ein Menu hinsetzen</li><li>In der Menueleiste ein paar Funktionen hinzufuegen</li><li>Hier zwei Buttons, einer zum Bestaetigen und einer zum Abbrechen</li></ul><p>Das klingt unproblematisch, aber in den grossen Unternehmensrichtlinien sind diese Begriffe keine verschwommenen Konzepte, sondern sehr fein unterteilt.</p><table tabindex="0"><thead><tr><th style="text-align:left;">Was man umgangssprachlich sagt</th><th style="text-align:left;">Offizieller Originaltext</th><th style="text-align:left;">Kurz gesagt</th></tr></thead><tbody><tr><td style="text-align:left;">&quot;Ein Menu erstellen&quot;</td><td style="text-align:left;">Apple: <a href="https://developer.apple.com/design/human-interface-guidelines/menus" target="_blank" rel="noreferrer">&quot;A menu reveals its options...&quot;</a></td><td style="text-align:left;"><code>Menu</code> dient der Durchfuehrung von Aktionen</td></tr><tr><td style="text-align:left;">&quot;Funktionen in die Menueleiste&quot;</td><td style="text-align:left;">Apple: <a href="https://developer.apple.com/design/human-interface-guidelines/menus" target="_blank" rel="noreferrer">&quot;menu bar menus contain all the commands...&quot;</a></td><td style="text-align:left;">Dies ist das Befehlsmenue oben in der App</td></tr><tr><td style="text-align:left;">&quot;Ein Dropdown erstellen&quot;</td><td style="text-align:left;">Apple: <a href="https://developer.apple.com/library/archive/documentation/Cocoa/Conceptual/MenuList/Articles/ManagingPopUpItems.html" target="_blank" rel="noreferrer">&quot;A pop-up list lets the user choose one option among several.&quot;</a></td><td style="text-align:left;"><code>pop-up</code> dient der Auswahl eines Werts aus einer Liste</td></tr><tr><td style="text-align:left;">&quot;Auch ein Dropdown&quot;</td><td style="text-align:left;">Apple: <a href="https://developer.apple.com/library/archive/documentation/Cocoa/Conceptual/MenuList/Articles/ManagingPopUpItems.html" target="_blank" rel="noreferrer">&quot;A pull-down list is generally used for selecting commands in a specific context.&quot;</a></td><td style="text-align:left;"><code>pull-down</code> oeffnet sich fuer die aktuelle Aktion</td></tr><tr><td style="text-align:left;">&quot;Menu kann man auch zum Filtern nutzen&quot;</td><td style="text-align:left;">Fluent: <a href="https://fluent2.microsoft.design/components/web/react/core/menu/usage" target="_blank" rel="noreferrer">&quot;If you need to collect information from people, try a select, dropdown, or combobox instead.&quot;</a></td><td style="text-align:left;"><code>Menu</code> ist nicht zur Werterfassung gedacht</td></tr><tr><td style="text-align:left;">&quot;Menu kann man auch als Navigation nutzen&quot;</td><td style="text-align:left;">Material: <a href="https://m1.material.io/components/menus.html" target="_blank" rel="noreferrer">&quot;Menus should not be used as a primary method for navigation within an app.&quot;</a></td><td style="text-align:left;"><code>Menu</code> ist keine Hauptnavigation</td></tr><tr><td style="text-align:left;">&quot;Button einfach OK / Cancel schreiben&quot;</td><td style="text-align:left;">Apple: <a href="https://developer.apple.com/design/human-interface-guidelines/alerts" target="_blank" rel="noreferrer">&quot;Always use &#39;Cancel&#39; to title a button that cancels the alert&#39;s action.&quot;</a></td><td style="text-align:left;">Button-Text darf nicht willkuerlich sein</td></tr></tbody></table><blockquote><p>Die Zitate in der Tabelle sind direkt klickbar und fuehren zur entsprechenden offiziellen Seite.</p></blockquote><p>Genau das ist es, woran man beim ersten echten Blick in Designrichtlinien am leichtesten erschrickt:</p><blockquote><p>Wir glauben oft, wir wuerden ueber UI diskutieren, aber tatsaechlich kommunizieren wir meistens nur mit einer Reihe vager Begriffe.</p></blockquote><p>Apple wuerde niemals nur sagen &quot;ein Menu erstellen&quot;; es wuerde weiter unterscheiden in:</p><ul><li><code>menu</code></li><li><code>menu bar menu</code></li><li><code>pop-up button</code></li><li><code>pull-down button</code></li><li><code>context menu</code></li></ul><p>Fluent wuerde niemals nur sagen &quot;ein Dropdown&quot;; es wuerde weiter unterscheiden in:</p><ul><li><code>menu</code></li><li><code>dropdown</code></li><li><code>select</code></li><li><code>combobox</code></li></ul><p>Genau das ist die Notwendigkeit von Designrichtlinien.</p><p>Sie dienen nicht dazu, Seiten professioneller wirken zu lassen, sondern sicherzustellen, dass im Team bei UI-Diskussionen nicht jeder etwas anderes im Kopf hat.</p><h2 id="was-du-lernen-wirst" tabindex="-1">Was du lernen wirst <a class="header-anchor" href="#was-du-lernen-wirst" aria-label="Permalink to “Was du lernen wirst”">​</a></h2><ol><li>Warum man beim Entwerfen von Seiten und Buttons zuerst die Designrichtlinien lesen sollte</li><li>Welche Inhalte der Richtlinien von Apple, Material, Fluent und Atlassian am referenzwuerdigsten sind</li><li>Wie man &quot;Seitenhierarchie&quot; und &quot;Button-Hierarchie&quot; klar gestaltet</li><li>Wie man AI dazu bringt, sich an den Richtlinien anderer zu orientieren, um Seiten und Buttons zu generieren</li></ol><h2 id="_1-warum-designrichtlinien-dir-helfen-seiten-klar-zu-gestalten" tabindex="-1">1. Warum Designrichtlinien dir helfen, Seiten klar zu gestalten <a class="header-anchor" href="#_1-warum-designrichtlinien-dir-helfen-seiten-klar-zu-gestalten" aria-label="Permalink to “1. Warum Designrichtlinien dir helfen, Seiten klar zu gestalten”">​</a></h2><p>Nach dem Lesen der obigen Originalzitate faellt ein Schluesselpunkt auf:</p><p><strong>Designrichtlinien sind kein zusaetzlicher Luxus, sondern sorgen zunaechst dafuer, dass die Begriffe praezise verwendet werden.</strong></p><p>Viele Seiten sehen nicht gut aus, nicht weil die Farbgebung nicht hochwertig genug ist, sondern weil die Informationsebenen chaotisch sind.</p><p>Viele Buttons sind nicht benutzerfreundlich, nicht weil die Abrundung falsch ist, sondern weil:</p><ul><li>Es zu viele Haupt-Buttons gibt und die Nutzer nicht wissen, welchen sie klicken sollen</li><li>Gefaehrliche und normale Buttons aehnlich aussehen</li><li>Alle Buttons auf der Seite um Aufmerksamkeit konkurrieren</li><li>Button-Stil und Semantik ueber verschiedene Seiten hinweg inkonsistent sind</li></ul><p>Ausgereifte Designrichtlinien loesen genau diese Probleme. Sie definieren in der Regel:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Inhalt der Richtlinie</th><th style="text-align:left;">Welches Problem es loest</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Seitenhierarchie</strong></td><td style="text-align:left;">Wohin man zuerst schaut, wohin spaeter, wie Informationen organisiert werden</td></tr><tr><td style="text-align:left;"><strong>Visuelle Grundlagen</strong></td><td style="text-align:left;">Wie Farben, Abstaende, Schriften, Abrundungen und Schatten vereinheitlicht werden</td></tr><tr><td style="text-align:left;"><strong>Button-Hierarchie</strong></td><td style="text-align:left;">Wie Haupt-, Neben-, Text- und Gefahren-Buttons unterschieden werden</td></tr><tr><td style="text-align:left;"><strong>Zustandsregeln</strong></td><td style="text-align:left;">Wie hover, focus, disabled und loading dargestellt werden</td></tr><tr><td style="text-align:left;"><strong>Interaktionssemantik</strong></td><td style="text-align:left;">Welcher Button &quot;bestaetigen&quot;, &quot;abbrechen&quot; und &quot;weitere Aktionen&quot; bedeutet</td></tr></tbody></table><p>Designrichtlinien liefern also nicht einfach einen &quot;Skin&quot;, sondern ein <strong>Beurteilungskriterium</strong>.</p><h2 id="_2-worauf-man-bei-den-grossen-unternehmensrichtlinien-achten-sollte" tabindex="-1">2. Worauf man bei den grossen Unternehmensrichtlinien achten sollte <a class="header-anchor" href="#_2-worauf-man-bei-den-grossen-unternehmensrichtlinien-achten-sollte" aria-label="Permalink to “2. Worauf man bei den grossen Unternehmensrichtlinien achten sollte”">​</a></h2><h3 id="_2-1-von-apple-lernen-definitionen-fein-genug-zu-fassen" tabindex="-1">2.1 Von Apple lernen: &quot;Definitionen fein genug zu fassen&quot; <a class="header-anchor" href="#_2-1-von-apple-lernen-definitionen-fein-genug-zu-fassen" aria-label="Permalink to “2.1 Von Apple lernen: &quot;Definitionen fein genug zu fassen&quot;”">​</a></h3><p>Das Lernwertste bei Apple ist nicht nur die visuelle Zurueckhaltung, sondern dass es Konzepte sehr fein definiert.</p><p>Das, was in vielen Teams nur &quot;Menu&quot; oder &quot;Dropdown&quot; heisst, wird bei Apple weiter unterteilt:</p><ul><li><code>menu</code>: Eine Gruppe von Befehlen, Optionen oder Zustaenden</li><li><code>menu bar menu</code>: App-weite Befehlssammlung</li><li><code>pop-up button</code>: Einen Wert auswaehlen</li><li><code>pull-down button</code>: Im aktuellen Kontext einen Befehl ausloesen</li><li><code>context menu</code>: Haeufige Aktionen bezogen auf das aktuelle Objekt oder die aktuelle Aufgabe</li></ul><p>Diese Unterscheidung ist sehr wichtig, da sie sich direkt darauf auswirkt:</p><ul><li>Ob die Komponente zur Werterfassung oder zur Aktionsausfuehrung dient</li><li>Ob sie zum Seitenbereich oder zur App-Ebene gehoert</li><li>Ob sie den aktuell ausgewaehlten Wert dauerhaft anzeigen soll oder nur temporaer Befehle aufklappt</li></ul><p>Wenn du in dieser Granularitaet zu denken beginnst, werden deine Seiten sofort deutlich klarer.</p><h3 id="_2-2-von-apple-lernen-seitenhierarchie-und-zurueckhaltung" tabindex="-1">2.2 Von Apple lernen: Seitenhierarchie und Zurueckhaltung <a class="header-anchor" href="#_2-2-von-apple-lernen-seitenhierarchie-und-zurueckhaltung" aria-label="Permalink to “2.2 Von Apple lernen: Seitenhierarchie und Zurueckhaltung”">​</a></h3><p>Die Apple Human Interface Guidelines eignen sich besonders gut, um zwei Dinge zu lernen:</p><ul><li>Wie Seiten eine klare Hierarchie aufbauen</li><li>Wie Steuerelemente eindeutig bleiben, ohne aufdringlich zu wirken</li></ul><p>Apple betont <code>Hierarchy</code>, <code>Harmony</code> und <code>Consistency</code>. Das bedeutet, dass beim Seitendesign folgende Fragen beantwortet werden muessen:</p><ul><li>Was ist die wichtigste Information auf der aktuellen Seite?</li><li>Was ist die Hauptaufgabe des Nutzers?</li><li>Welche Operation am auffaelligsten sein sollte und welche in den Hintergrund gehoert</li></ul><p>Wenn du dich an Apple orientierst, kannst du besonders folgende Aspekte uebernehmen:</p><ul><li>Die Informationen auf dem ersten Bildschirm sollten nicht zu fragmentiert sein; der Kerninhalt steht im Fokus</li><li>Ordnung durch Freiraum, Schriftgroessen und Gruppierung schaffen, statt viele Rahmen zu stapeln</li><li>Nicht alle Buttons sollten stark hervorgehoben sein; nur die wichtigsten Aktionen sollten am auffaelligsten sein</li></ul><h3 id="_2-3-von-material-lernen-klarere-seitenstruktur" tabindex="-1">2.3 Von Material lernen: Klarere Seitenstruktur <a class="header-anchor" href="#_2-3-von-material-lernen-klarere-seitenstruktur" aria-label="Permalink to “2.3 Von Material lernen: Klarere Seitenstruktur”">​</a></h3><p>Material Design eignet sich besonders gut, um zu lernen, &quot;wie Seiten Aufgabenstroeme organisieren&quot;.</p><p>Viele seiner Komponenten- und Layoutrichtlinien zielen darauf ab, Folgendes klarzustellen:</p><ul><li>Ob eine Seite zum Durchsuchen oder zur Aufgabenausfuehrung dient</li><li>Ob die aktuelle Seite Nutzer zum Lesen, Auswaehlen oder Absenden veranlassen soll</li><li>Welche Elemente auf einer Seite stabil wiederkehren sollten und welche sich dynamisch an den Kontext anpassen</li></ul><p>Wenn du dich an Material orientierst, kannst du besonders folgende Aspekte uebernehmen:</p><ul><li>Seitenbereiche klar strukturieren, Modulverantwortlichkeiten eindeutig definieren</li><li>Navigation, Inhalts- und Aktionsbereiche sauber trennen</li><li>Unterschiedliche Button-Stile entsprechen unterschiedlichen Operationsprioritaeten</li></ul><h3 id="_2-4-von-fluent-lernen-komponentengrenzen-und-button-hierarchie" tabindex="-1">2.4 Von Fluent lernen: Komponentengrenzen und Button-Hierarchie <a class="header-anchor" href="#_2-4-von-fluent-lernen-komponentengrenzen-und-button-hierarchie" aria-label="Permalink to “2.4 Von Fluent lernen: Komponentengrenzen und Button-Hierarchie”">​</a></h3><p>Fluent 2 eignet sich besonders fuer Backends, Werkzeug-Produkte und komplexe Formularsysteme. Das Lernenswerteste daran ist, dass es dir direkt sagt: &quot;Konzepte nicht vermischen.&quot;</p><p>Es schreibt beispielsweise ausdruecklich: Wenn du &quot;collect information&quot; moechtest, solltest du nicht weiterhin <code>menu</code> verwenden, sondern <code>select</code>, <code>dropdown</code> oder <code>combobox</code> in Betracht ziehen.</p><p>Dieser Satz ist sehr wichtig, da er das, was viele Menschen fuer &quot;ungefaehr gleich&quot; halten, aufbrechen laesst.</p><p>Fluent 2 legt auch grossen Wert auf:</p><ul><li>Aktionsebenen</li><li>Komponenten-Semantikgrenzen</li><li>Klarheit in dichten Informationsszenarien</li></ul><p>Wenn du dich an Fluent orientierst, um Buttons zu gestalten, kannst du besonders folgende Aspekte uebernehmen:</p><ul><li><code>Primary button</code> fuer die aktuell wichtigste Aktion</li><li><code>Secondary button</code> fuer unterstuetzende Aktionen</li><li><code>Subtle</code> und <code>Transparent</code> als schwach betonte Buttons fuer Aktionen, die den Hauptprozess nicht stoeren sollten</li><li>Je mehr Buttons auf einer Seite, desto wichtiger ist die Kontrolle der visuellen Prioritaet</li></ul><h3 id="_2-5-von-atlassian-lernen-systematisches-verwalten-von-seiten-und-buttons" tabindex="-1">2.5 Von Atlassian lernen: Systematisches Verwalten von Seiten und Buttons <a class="header-anchor" href="#_2-5-von-atlassian-lernen-systematisches-verwalten-von-seiten-und-buttons" aria-label="Permalink to “2.5 Von Atlassian lernen: Systematisches Verwalten von Seiten und Buttons”">​</a></h3><p>Das Atlassian Design System eignet sich besonders fuer den Fall, dass &quot;ein Team viele Seiten erstellt&quot;. Es betont:</p><ul><li>foundations als gemeinsame Basis</li><li>tokens als Methode zur einheitlichen visuellen Entscheidungsfindung</li><li>components als wiederholt verwendete Interaktionsbausteine</li></ul><p>Wenn du dich an Atlassian orientierst, um Seiten und Buttons zu gestalten, ist das Wertvollste:</p><ul><li>Button-Groesse, Farbe, Abrundung und Abstaende als einheitliche Regeln definieren</li><li>Den Rhythmus des Seitenlayouts festigen</li><li>Sicherstellen, dass verschiedene Seiten trotz unterschiedlicher Inhalte eine einheitliche Struktursprache verwenden</li></ul><h2 id="_3-worauf-man-beim-entwerfen-von-seiten-aus-den-richtlinien-absehen-sollte" tabindex="-1">3. Worauf man beim Entwerfen von Seiten aus den Richtlinien absehen sollte <a class="header-anchor" href="#_3-worauf-man-beim-entwerfen-von-seiten-aus-den-richtlinien-absehen-sollte" aria-label="Permalink to “3. Worauf man beim Entwerfen von Seiten aus den Richtlinien absehen sollte”">​</a></h2><p>Wenn du ein Designsystem betrachtest, frage nicht zuerst &quot;Sieht diese Seite gut aus?&quot;, sondern stelle zunaechst die folgenden Fragen.</p><h3 id="_3-1-erster-blick-auf-die-seite-ist-die-hierarchie-klar" tabindex="-1">3.1 Erster Blick auf die Seite: Ist die Hierarchie klar? <a class="header-anchor" href="#_3-1-erster-blick-auf-die-seite-ist-die-hierarchie-klar" aria-label="Permalink to “3.1 Erster Blick auf die Seite: Ist die Hierarchie klar?”">​</a></h3><p>Eine Seite sollte in der Regel mindestens drei Ebenen haben:</p><ul><li><strong>Hauptinformation</strong>: Der wichtigste Inhalt der aktuellen Seite</li><li><strong>Unterstuetzende Informationen</strong>: Inhalte zum besseren Verstaendnis oder zur Ergaenzung</li><li><strong>Sekundaere Aktionen</strong>: Aktionen, die die Hauptaufgabe nicht stoeren sollten</li></ul><p>Wenn die drei Ebenen nicht deutlich getrennt sind, wirkt die Seite &quot;alles wichtig&quot; -- was gleichbedeutend mit &quot;nichts ist wichtig&quot; ist.</p><h3 id="_3-2-seitenlayout-dient-es-der-aufgabe-oder-stapelt-es-nur-module" tabindex="-1">3.2 Seitenlayout: Dient es der Aufgabe oder stapelt es nur Module? <a class="header-anchor" href="#_3-2-seitenlayout-dient-es-der-aufgabe-oder-stapelt-es-nur-module" aria-label="Permalink to “3.2 Seitenlayout: Dient es der Aufgabe oder stapelt es nur Module?”">​</a></h3><p>Beim Durcharbeiten der Richtlinien solltest du besonders darauf achten:</p><ul><li>Ob der Titelbereich das Seitenziel klar benennt</li><li>Ob der Hauptinhaltsbereich um die Aufgabe herum organisiert ist</li><li>Ob die Aktions-Buttons nah an den zugehoerigen Inhalten platziert sind</li><li>Ob unwichtige Informationen abgeschwaecht wurden</li></ul><h3 id="_3-3-haben-die-aktionen-auf-der-seite-eine-prioritaet" tabindex="-1">3.3 Haben die Aktionen auf der Seite eine Prioritaet? <a class="header-anchor" href="#_3-3-haben-die-aktionen-auf-der-seite-eine-prioritaet" aria-label="Permalink to “3.3 Haben die Aktionen auf der Seite eine Prioritaet?”">​</a></h3><p>Viele Seiten haben auf den ersten Blick 6 Buttons, und jeder sieht wie ein CTA aus -- das ist ein klassischer Hierarchieverlust.</p><p>Sinnvoller ist:</p><ul><li>Ein Bereich hat in der Regel nur eine Hauptaktion</li><li>Sekundaere Aktionen koennen mit Umrandungen, Text-Buttons oder schwaecherem Stil dargestellt werden</li><li>Risikoaktionen sollten nicht genauso aussehen wie die Hauptaktion</li></ul><h2 id="_4-worauf-man-beim-entwerfen-von-buttons-aus-den-richtlinien-absehen-sollte" tabindex="-1">4. Worauf man beim Entwerfen von Buttons aus den Richtlinien absehen sollte <a class="header-anchor" href="#_4-worauf-man-beim-entwerfen-von-buttons-aus-den-richtlinien-absehen-sollte" aria-label="Permalink to “4. Worauf man beim Entwerfen von Buttons aus den Richtlinien absehen sollte”">​</a></h2><p>Buttons sind der am leichtesten &quot;beilaeufig gestaltete&quot; Teil, aber auch der Teil, der am meisten darueber verraet, ob ein System ausgereift ist.</p><h3 id="_4-1-buttons-zunaechst-nach-semantik-unterscheiden-dann-nach-stil" tabindex="-1">4.1 Buttons zunaechst nach &quot;Semantik&quot; unterscheiden, dann nach &quot;Stil&quot; <a class="header-anchor" href="#_4-1-buttons-zunaechst-nach-semantik-unterscheiden-dann-nach-stil" aria-label="Permalink to “4.1 Buttons zunaechst nach &quot;Semantik&quot; unterscheiden, dann nach &quot;Stil&quot;”">​</a></h3><p>Denke nicht zuerst &quot;blauer oder schwarzer Button&quot;, sondern darueber, welche Rolle dieser Button spielt.</p><p>Haeufige Button-Rollen koennen wie folgt kategorisiert werden:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Button-Typ</th><th style="text-align:left;">Funktion</th><th style="text-align:left;">Haeufige Stilstrategie</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Primary</strong></td><td style="text-align:left;">Die wichtigste Aktion im aktuellen Bereich</td><td style="text-align:left;">Ausgefuellt, hoher Kontrast, am auffaelligsten</td></tr><tr><td style="text-align:left;"><strong>Secondary</strong></td><td style="text-align:left;">Unterstuetzende Aktionen</td><td style="text-align:left;">Umrandet oder eine Stufe schwaecher betont</td></tr><tr><td style="text-align:left;"><strong>Tertiary / Text</strong></td><td style="text-align:left;">Schwache Aktionen</td><td style="text-align:left;">Text oder geringer visueller Anteil</td></tr><tr><td style="text-align:left;"><strong>Destructive</strong></td><td style="text-align:left;">Risikoaktionen wie Loeschen, Deaktivieren, Leeren</td><td style="text-align:left;">Warnfarbe oder eindeutiger Risiko-Stil</td></tr><tr><td style="text-align:left;"><strong>Icon button</strong></td><td style="text-align:left;">Lokale Werkzeugaktionen</td><td style="text-align:left;">Kompakt, nah am Kontext</td></tr></tbody></table><h3 id="_4-2-nicht-zu-viele-primary-buttons-auf-einer-seite" tabindex="-1">4.2 Nicht zu viele Primary Buttons auf einer Seite <a class="header-anchor" href="#_4-2-nicht-zu-viele-primary-buttons-auf-einer-seite" aria-label="Permalink to “4.2 Nicht zu viele Primary Buttons auf einer Seite”">​</a></h3><p>Das ist die haeufigste Falle fuer Anfaenger.</p><p>Wenn 4 Haupt-Buttons auf einer Seite sind, gibt es faktisch keinen Haupt-Button. Die Bedeutung eines Haupt-Buttons besteht ja gerade darin, &quot;dem Nutzer zu sagen, was er jetzt am besten tun sollte&quot;.</p><p>Du kannst die gemeinsame Praxis vieler Designsysteme uebernehmen:</p><ul><li>Ein Hauptbereich hat in der Regel nur einen Haupt-Button</li><li>Abbrechen, Zurueck und Schliessen konkurrieren in der Regel nicht auf derselben Ebene mit dem Bestaetigungs-Button</li><li>Weitere Aktionen in sekundaere Buttons oder Menus auslagern</li></ul><h3 id="_4-3-buttons-muessen-zustandsaenderungen-ausdruecken-koennen" tabindex="-1">4.3 Buttons muessen Zustandsaenderungen ausdruecken koennen <a class="header-anchor" href="#_4-3-buttons-muessen-zustandsaenderungen-ausdruecken-koennen" aria-label="Permalink to “4.3 Buttons muessen Zustandsaenderungen ausdruecken koennen”">​</a></h3><p>Designrichtlinien beschreiben Button-Zustaende in der Regel sehr detailliert:</p><ul><li>Standardzustand</li><li>Hover-Zustand</li><li>Fokus-Zustand</li><li>Deaktivierter Zustand</li><li>Ladezustand</li><li>Gefahrenzustand</li></ul><p>Das ist wichtig, da ein Button kein statisches Bild ist, sondern eines der am haeufigsten ausgeloesten Steuerelemente waehrend der Benutzerinteraktion.</p><h3 id="_4-4-button-beschriftung-gehoert-ebenfalls-zum-design" tabindex="-1">4.4 Button-Beschriftung gehoert ebenfalls zum Design <a class="header-anchor" href="#_4-4-button-beschriftung-gehoert-ebenfalls-zum-design" aria-label="Permalink to “4.4 Button-Beschriftung gehoert ebenfalls zum Design”">​</a></h3><p>Die Button-Beschriftung ist nicht nur eine &quot;Textfrage&quot; -- sie beeinflusst das Nutzerverstaendnis direkt.</p><p>Beispiele:</p><ul><li><code>Speichern</code></li><li><code>Aenderungen speichern</code></li><li><code>Sofort veroeffentlichen</code></li><li><code>Projekt loeschen</code></li><li><code>In den Papierkorb verschieben</code></li></ul><p>Diese Beschriftungen vermitteln vollkommen unterschiedliche psychologische Erwartungen. Ausgereifte Richtlinien verlangen in der Regel, dass Button-Labels die Aktion klar ausdruecken, anstatt vage Begriffe zu verwenden.</p><h2 id="_5-eine-sehr-praktische-checkliste-fuer-seiten-und-button-design" tabindex="-1">5. Eine sehr praktische Checkliste fuer Seiten- und Button-Design <a class="header-anchor" href="#_5-eine-sehr-praktische-checkliste-fuer-seiten-und-button-design" aria-label="Permalink to “5. Eine sehr praktische Checkliste fuer Seiten- und Button-Design”">​</a></h2><p>Wenn du selbst eine Seite entwirfst, kannst du zunaechst diese Checkliste schnell durchgehen:</p><h3 id="seiten-checkliste" tabindex="-1">Seiten-Checkliste <a class="header-anchor" href="#seiten-checkliste" aria-label="Permalink to “Seiten-Checkliste”">​</a></h3><ul><li>Ob der Seitentitel die aktuelle Aufgabe klar beschreibt</li><li>Ob die wichtigste Information auf dem ersten Bildschirm sofort sichtbar ist</li><li>Ob die Seite nach dem Aufgabenfluss und nicht nach dem organisiert ist, was einem gerade einfaellt</li><li>Ob es in einem Bereich nur eine Hauptaktion gibt</li><li>Ob unwichtige Inhalte angemessen abgeschwaecht wurden</li></ul><h3 id="button-checkliste" tabindex="-1">Button-Checkliste <a class="header-anchor" href="#button-checkliste" aria-label="Permalink to “Button-Checkliste”">​</a></h3><ul><li>Ist dieser Button eine Haupt- oder Nebention?</li><li>Warum sollte dieser Button auffaelliger sein als die anderen?</li><li>Gibt es zu viele Haupt-Buttons auf der Seite?</li><li>Sind Gefahrenaktionen eindeutig markiert?</li><li>Ist die Button-Beschriftung konkret genug?</li></ul><h2 id="_6-wie-man-ai-dazu-bringt-sich-an-den-richtlinien-anderer-zu-orientieren" tabindex="-1">6. Wie man AI dazu bringt, sich an den Richtlinien anderer zu orientieren <a class="header-anchor" href="#_6-wie-man-ai-dazu-bringt-sich-an-den-richtlinien-anderer-zu-orientieren" aria-label="Permalink to “6. Wie man AI dazu bringt, sich an den Richtlinien anderer zu orientieren”">​</a></h2><p>Dieser Abschnitt ist am praktischsten.</p><p>Viele Menschen sagen zu AI beim Entwerfen von Seiten nur:</p><div class="language-md"><button title="Copy Code" class="copy"></button><span class="lang">md</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Mach mir eine Einstellungsseite, die etwas hochwertiger aussehen soll, im Apple-Stil</span></span></code></pre></div><p>Solche Prompts sind zu vage -- AI kann am Ende meist nur &quot;weisser Hintergrund, abgerundete Ecken, Schatten&quot; imitieren.</p><p>Fuer Anfaenger ist der praktischste Ansatz nicht, selbst eine lange Zusammenfassung zu schreiben, sondern die <strong>Schluesselsaetze aus dem Originaltext der Richtlinie</strong> direkt in AI einzufuegen.</p><p>Das hat zwei Vorteile:</p><ul><li>Du musst die Designphilosophie nicht selbst &quot;uebersetzen&quot;</li><li>AI kann die Seite und die Buttons leichter gemaess den offiziellen Definitionen verstehen</li></ul><h3 id="_6-1-beispiel-1-ai-bitten-eine-einstellungsseite-nach-apple-design-zu-erstellen" tabindex="-1">6.1 Beispiel 1: AI bitten, eine Einstellungsseite nach Apple-Design zu erstellen <a class="header-anchor" href="#_6-1-beispiel-1-ai-bitten-eine-einstellungsseite-nach-apple-design-zu-erstellen" aria-label="Permalink to “6.1 Beispiel 1: AI bitten, eine Einstellungsseite nach Apple-Design zu erstellen”">​</a></h3><p>Zunaechst ein Originalzitat von Apple:</p><blockquote><p><a href="https://developer.apple.com/design/human-interface-guidelines/" target="_blank" rel="noreferrer">&quot;Establish a clear visual hierarchy...&quot;</a></p></blockquote><p>Du kannst AI direkt so ansprechen:</p><div class="language-md"><button title="Copy Code" class="copy"></button><span class="lang">md</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Beziehe dich auf diesen Satz aus den Apple Human Interface Guidelines:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&quot;Establish a clear visual hierarchy...&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Erstelle eine Kontosicherheit-Einstellungsseite.</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Die Seitenhierarchie soll klar sein, wichtige Informationen zuerst, ordentlich gruppiert.</span></span></code></pre></div><p>Der Punkt dabei ist: Du musst nicht viel selbst erklaeren -- einfach den Originaltext von Apple einfuegen.</p><h3 id="_6-2-beispiel-2-ai-bitten-backend-buttons-nach-fluent-zu-gestalten" tabindex="-1">6.2 Beispiel 2: AI bitten, Backend-Buttons nach Fluent zu gestalten <a class="header-anchor" href="#_6-2-beispiel-2-ai-bitten-backend-buttons-nach-fluent-zu-gestalten" aria-label="Permalink to “6.2 Beispiel 2: AI bitten, Backend-Buttons nach Fluent zu gestalten”">​</a></h3><p>Zunaechst ein Originalzitat von Fluent:</p><blockquote><p><a href="https://fluent2.microsoft.design/components/web/react/core/button/usage" target="_blank" rel="noreferrer">&quot;Only use one primary button in a layout...&quot;</a></p></blockquote><p>Du kannst AI direkt so ansprechen:</p><div class="language-md"><button title="Copy Code" class="copy"></button><span class="lang">md</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Beziehe dich auf diesen Satz aus Fluent 2:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&quot;Only use one primary button in a layout...&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Gestalte die Buttons fuer ein Team-Management-Backend.</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Der &quot;Mitglied hinzufuegen&quot;-Button am auffaelligsten, Export, Filter, weitere Aktionen schwaecher, und der Loeschen-Button gesondert hervorheben.</span></span></code></pre></div><p>Dieser Satz eignet sich hervorragend fuer Anfaenger, da er AI direkt sagt: In einem Bereich nicht zu viele Haupt-Buttons platzieren.</p><h3 id="_6-3-beispiel-3-ai-bitten-sich-gleichzeitig-an-seiten-und-button-richtlinien-zu-orientieren" tabindex="-1">6.3 Beispiel 3: AI bitten, sich gleichzeitig an Seiten- und Button-Richtlinien zu orientieren <a class="header-anchor" href="#_6-3-beispiel-3-ai-bitten-sich-gleichzeitig-an-seiten-und-button-richtlinien-zu-orientieren" aria-label="Permalink to “6.3 Beispiel 3: AI bitten, sich gleichzeitig an Seiten- und Button-Richtlinien zu orientieren”">​</a></h3><p>Du kannst auch zwei Originalzitate gleichzeitig einfuegen und AI bitten, sich sowohl an der Seiten- als auch an der Button-Richtlinie zu orientieren:</p><blockquote><p>Apple: <a href="https://developer.apple.com/design/human-interface-guidelines/" target="_blank" rel="noreferrer">&quot;Establish a clear visual hierarchy...&quot;</a></p><p>Fluent: <a href="https://fluent2.microsoft.design/components/web/react/core/button/usage" target="_blank" rel="noreferrer">&quot;Only use one primary button in a layout...&quot;</a></p></blockquote><p>Dann schreibst du einfach:</p><div class="language-md"><button title="Copy Code" class="copy"></button><span class="lang">md</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Beziehe dich auf die folgenden zwei Designrichtlinien-Originalsaetze:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Apple: &quot;Establish a clear visual hierarchy...&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Fluent: &quot;Only use one primary button in a layout...&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Erstelle eine Projektdetailseite.</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Die Seite enthaelt Projektbeschreibung, Mitglieder, letzte Aktivitaeten und einen Einstellungseinstieg.</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Die Seitenhierarchie soll klar sein, nur einen Haupt-Button behalten, die anderen schwaecher darstellen.</span></span></code></pre></div><p>Dieser Ansatz eignet sich besonders fuer Anfaenger, da du nur den Originaltext kopieren und ein bis zwei Saetze eigener Anforderungen hinzufuegen musst.</p><h2 id="_7-wie-man-ai-dazu-bringt-sich-an-button-richtlinien-zu-orientieren-um-direkt-button-designs-zu-generieren" tabindex="-1">7. Wie man AI dazu bringt, sich an Button-Richtlinien zu orientieren, um direkt Button-Designs zu generieren <a class="header-anchor" href="#_7-wie-man-ai-dazu-bringt-sich-an-button-richtlinien-zu-orientieren-um-direkt-button-designs-zu-generieren" aria-label="Permalink to “7. Wie man AI dazu bringt, sich an Button-Richtlinien zu orientieren, um direkt Button-Designs zu generieren”">​</a></h2><p>Wenn du zunaechst nur Buttons erstellen moechtest, kannst du auch direkt die Originaltexte der Button-Richtlinien einfuegen.</p><p>Beispielsweise ist die Definition von Atlassian fuer Buttons sehr kurz:</p><blockquote><p><a href="https://atlassian.design/components/button/" target="_blank" rel="noreferrer">&quot;A button triggers an event or action.&quot;</a></p></blockquote><p>Du kannst AI so fragen:</p><div class="language-md"><button title="Copy Code" class="copy"></button><span class="lang">md</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Beziehe dich auf diesen Satz von Atlassian:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&quot;A button triggers an event or action.&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Gestalte einen Satz von Backend-Button-Stilen.</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Ich moechte einen Haupt-Button, einen Neben-Button und einen Loeschen-Button, und erzaehle mir bitte, wo jeweils welcher verwendet wird.</span></span></code></pre></div><p>Diese Art von Prompt eignet sich besonders fuer Anfaenger -- im Grunde heisst es &quot;Originaltext einfuegen + Anforderungen nennen&quot;.</p><h2 id="_8-zusammenfassung" tabindex="-1">8. Zusammenfassung <a class="header-anchor" href="#_8-zusammenfassung" aria-label="Permalink to “8. Zusammenfassung”">​</a></h2><p>Sich an UI-Designrichtlinien zu orientieren, wenn man Seiten und Buttons entwirft, heisst nicht &quot;auszusehen wie jemand anderes&quot;, sondern folgende Dinge zu lernen:</p><ol><li>Seiten mit Hierarchie organisieren, anstatt Inhalte einfach zu stapeln</li><li>Operationsprioritaeten durch Button-Stufung ausdruecken, anstatt alle Buttons gleich aufdringlich zu machen</li><li>Sich bei der Gestaltung an den Definitionen, Grenzen und Beurteilungskriterien der Designrichtlinien orientieren</li><li>Wenn AI sich an den Richtlinien anderer orientiert, sollte sie sich an &quot;Prinzipien und Struktur&quot; orientieren, nicht nur an der Oberflaeche</li></ol><p>Wenn du Richtlinien so verwendest, referenzierst du nicht nur einen Stil, sondern eine ausgereifte Design-Denkweise.</p><hr><h2 id="referenzmaterialien" tabindex="-1">Referenzmaterialien <a class="header-anchor" href="#referenzmaterialien" aria-label="Permalink to “Referenzmaterialien”">​</a></h2><p>Die folgenden Links stammen alle von offiziellen Designsystemen oder offizieller Dokumentation:</p><ul><li>Apple Human Interface Guidelines: <a href="https://developer.apple.com/design/human-interface-guidelines/" target="_blank" rel="noreferrer">Overview</a></li><li>Apple Human Interface Guidelines: <a href="https://developer.apple.com/design/human-interface-guidelines/menus" target="_blank" rel="noreferrer">Menus</a></li><li>Apple Human Interface Guidelines: <a href="https://developer.apple.com/design/human-interface-guidelines/alerts" target="_blank" rel="noreferrer">Alerts</a></li><li>Apple Human Interface Guidelines: <a href="https://developer.apple.com/design/human-interface-guidelines/buttons" target="_blank" rel="noreferrer">Buttons</a></li><li>Apple Archive: <a href="https://developer.apple.com/library/archive/documentation/Cocoa/Conceptual/MenuList/Articles/HowMenusWork.html" target="_blank" rel="noreferrer">How Menus Work</a></li><li>Apple Archive: <a href="https://developer.apple.com/library/archive/documentation/Cocoa/Conceptual/MenuList/Articles/ManagingPopUpItems.html" target="_blank" rel="noreferrer">Managing Pop-Up Buttons and Pull-Down Lists</a></li><li>Material Design: <a href="https://m3.material.io/components/buttons/overview" target="_blank" rel="noreferrer">Buttons overview</a></li><li>Material Design: <a href="https://m1.material.io/components/menus.html" target="_blank" rel="noreferrer">Menus</a></li><li>Microsoft Fluent 2: <a href="https://fluent2.microsoft.design/get-started/design" target="_blank" rel="noreferrer">Start designing</a></li><li>Microsoft Fluent 2: <a href="https://fluent2.microsoft.design/components/web/react/core/menu/usage" target="_blank" rel="noreferrer">Menu usage</a></li><li>Microsoft Fluent 2: <a href="https://fluent2.microsoft.design/components/web/react/core/button/usage" target="_blank" rel="noreferrer">Button usage</a></li><li>Atlassian Design System: <a href="https://atlassian.design/foundations/" target="_blank" rel="noreferrer">Foundations</a></li><li>Atlassian Design System: <a href="https://atlassian.design/components/button/" target="_blank" rel="noreferrer">Button</a></li></ul>`,146)])])}const p=n(s,[["render",r]]);export{g as __pageData,p as default};
